-- EXPAND the installed review pilot to the existing Year 9 and Year 10 courses.
-- Run this ENTIRE file in a NEW Supabase SQL Editor query, including BEGIN/COMMIT.
-- Requires 20261013_mistake_review_1a.sql, which is already installed for the pilot.
-- No content, attempts, progress, existing settings or schedules are replaced.
begin;
do $$ begin
 if to_regclass('public.mistake_review_settings') is null or to_regclass('public.mistake_review_schedules') is null
  or to_regprocedure('public._mistake_review_grade(jsonb,integer,integer,text)') is null then
  raise exception 'Install the complete 20261013_mistake_review_1a.sql migration first.';
 end if;
end $$;

-- Identify the original Year 9 course by its stable 1A lesson ID. Identify Year
-- 10 by existing question seed IDs, as the reusable lesson rollout does. Course
-- titles may be renamed. Ambiguous/missing courses abort instead of guessing.
do $$
declare year9 uuid; year10 uuid[];
begin
 select m.course_id into year9 from public.lessons l join public.modules m on m.id=l.module_id
 where l.id='1313fc50-2b9a-405d-a64a-7f385a1db1b8'::uuid;
 if year9 is null then raise exception 'The existing Year 9 course could not be identified.'; end if;
 select array_agg(scope.course_id) into year10 from (
  select m.course_id from public.questions q join public.lessons l on l.id=q.lesson_id join public.modules m on m.id=l.module_id
  where q.id=any(array[
